-- GENERATED by `wfi generate` from data/quest/quest-0005.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [5002] = { "Un messaggio per Maxwell", "Viaggia fino alle Burning Steppes e consegna la Bijou's Information al Marshal Maxwell.", "Sono una goblin di parola, {race}. Ora ascolta bene:\n\nQuesti orchi vengono usati soprattutto come bestie da soma e carne da cannone per lo stormo nero!\n\nIl loro vero capo è nientemeno che Nefarian, progenie di Deathwing. Ho anche scoperto dove si trovano i sottoposti di Nefarian in questa parte della cittadella.\n\nPorta questa mappa al Marshal Maxwell, nelle Burning Steppes. Vi è segnata la posizione di questi demoni, così da riconoscerli facilmente.", "Ah, {name}. È passato molto tempo.", "Coincide con gran parte di ciò che già sapevamo. Comunque, sono informazioni interessanti e piuttosto sfortunate.\n\nI segni su questa mappa si riveleranno preziosi per sfoltire la minaccia dei Blackrock.", 0xd738e388, 0x9f2ff06a, 0x01a3d183, 0x8dba76de, 0x762d90e6, "....." },
  [5048] = { "La buona Emma", "Trova Ol' Emma a Stormwind e verifica se è davvero Emma Felstone. Se lo è, forse le farà piacere il pacco che Janice Felstone ha preparato per lei.", "È un tantino scorbutica, e molto probabilmente fuori di testa... ma i registri indicano che Ol' Emma corrisponde al profilo di chi potrebbe essere Emma Felstone.\n\nForse hai visto Ol' Emma vagare per la città: parla da sola, il più delle volte in un borbottio senza senso. Comunque non fa male a nulla e a nessuno, quindi la gente la lascia stare.\n\nTutto considerato, direi che Ol' Emma è davvero Emma Felstone. Potresti provare a chiederle se il suo cognome è davvero Felstone.", "Ti direi di levarti dal mio prato, ma come vedi non ce l'ho.", "Il mio nome è davvero Emma Felstone: sei la prima persona in anni a chiamarmi così. Chi... chi sei?\n\nDici di aver conosciuto... mia sorella?! È ancora viva? Chi voglio prendere in giro, certo che no. Quando la piaga scoppiò a Lordaeron, mi ero preparata al peggio. Tanti membri della mia famiglia sono morti... o peggio. Ed eccomi qui, la pazza Ol' Emma, tutta sola. Cosa sei, una specie di <profanatore/profanatrice> di tombe? In cerca del tuo prossimo bersaglio?\n\nCosa... hai un pacco per me da parte di mia sorella?", 0x54e3cb36, 0xcab0ca91, 0x6b6f28a3, 0x8b85f199, 0x6b8bbfec, "....." },
  [5050] = { nil, "Riporta a Janice Felstone, nelle Western Plaguelands, il suo Good Luck Half-Charm.", "A quanto pare mi sbagliavo su di te, {name}, e per questo ti devo delle scuse. Mia sorella mi ha mandato diversi effetti personali, tra cui, buffo a dirsi, l'atto di proprietà della fattoria Felstone. Credo che per ora rinuncerò a reclamarla.\n\nSe lo spirito di mia sorella resta legato alla fattoria e non trova riposo, ti prego... potresti restituirle questo? È metà di un portafortuna che aveva; l'altra metà ce l'aveva suo marito.\n\nForse sapere che ho queste cose darà finalmente pace alla sua anima.", "John, tesoro... sei tu? All'improvviso ho così freddo...", "Restituisci la metà del portafortuna all'apparizione. Lei lo guarda, poi guarda te, in attesa.\n\n\"Caro, dove hai messo la tua metà del portafortuna? Non possiamo stare insieme se non abbiamo entrambe le metà. Caro... mi vedi?\"", nil, 0x9e16a7c6, 0x9652e8b3, 0xf293a279, 0xdb61f9a5, "m...." },
  [5061] = { "Forma acquatica", "Torna a Darnassus e mostra a Mathrengyl Bearwalker il Pendant of the Sea Lion.", "Hai completato le lezioni necessarie che vengono insegnate a tutti i giovani druidi prima che possano assumere un aspetto acquatico. Ora torna dal tuo istruttore, Mathrengyl Bearwalker, a Darnassus. Mostragli il tuo pendente e dimostragli di essere <pronto/pronta> a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare tutt'uno con l'acqua.\n\nAddio, giovane <druido/druida>. Ci parleremo di nuovo.", "Il tuo ritorno a Darnassus non è passato inosservato, ma mi servirà una prova delle lezioni apprese a Moonglade prima di insegnarti la forma acquatica.\n\nHai il Pendant of the Sea Lion?", "Davvero notevole, {name}. Sei <pronto/pronta> a imparare la tua forma acquatica, ed è un piacere per me insegnartela.\n\nInoltre, in riconoscimento di quanto hai ottenuto nelle due prove, ti do questo oggetto. Spero che sarà un'aggiunta gradita al tuo equipaggiamento di <protettore/protettrice> della natura e custode dell'equilibrio.", 0xb41f2b6a, 0x8aa8f24e, 0x489ae05e, 0x5ac3a51a, 0xd9b19ec7, "....." },
  [5066] = { "Chiamata alle armi: le Plaguelands!", "Cerca Commander Ashlam Valorfist. Il suo campo base si trova al Chillwind Camp, a nord delle Alterac Mountains.", "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl regno di Stormwind ha lanciato una chiamata alle armi! Tutte le persone abili sono invitate a prendere le armi contro l'oscura minaccia degli Scourge nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!\n\nEroi del reame, cercate Commander Ashlam Valorfist, che ha stabilito il suo campo base al Chillwind Camp, a nord delle Alterac Mountains!", nil, "<Benvenuto/Benvenuta> nelle Plaguelands, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, specialmente con la minaccia incombente della Scourge a nord e a nord-est. Sono lieto di sapere che lo squillo del dovere e del servizio al bene comune non è caduto nel vuoto con te!\n\nSe sei <pronto/pronta> a sporcarti le mani, qui al confine delle Plaguelands c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xb7a1f1f9, "...m." },
  [5081] = { "La missione di Maxwell", "Viaggia fino alla Blackrock Spire e distruggi il War Master Voone, l'Highlord Omokk e l'Overlord Wyrmthalak. Torna dal Marshal Maxwell quando avrai finito.", "Queste informazioni colmano le lacune della nostra, per il resto impeccabile, intelligence sulla Blackrock Spire.\n\nL'attacco dev'essere decisivo, {name}.\n\nPrima va distrutto il loro maestro di guerra, il troll Voone. Senza i suoi piani di battaglia, gli orchi Blackrock precipiteranno nel caos.\n\nPoi devi eliminare l'Highlord degli ogre, Omokk. I codardi ogre di Blackrock sono impotenti senza la sua guida.\n\nInfine, il signore della cittadella: Wyrmthalak. Con Wyrmthalak morto, il loro comando centrale resterà senza guida.", "Situazione?", "Ottimo lavoro, {name}. Per lo meno ci hai fatto guadagnare tempo: tempo prezioso, preziosissimo.", 0xc1d7f82a, 0x1da97ed4, 0x4be46f5e, 0x443e5ca0, 0x59df8873, "....." },
  [5089] = { nil, "Porta il General Drakkisath's Command al Marshal Maxwell, nelle Burning Steppes.", "Dal cadavere del serpente sconfitto recuperi quello che sembra un biglietto importante: una lettera del suo superiore, il generale Drakkisath, sul protocollo.\n\nL'istinto ti dice che dovresti portarla al Marshal Maxwell.", "Cos'hai lì, {name}?", "La faccenda si complica...", nil, 0x20e21738, 0x0981eb66, 0x421c38bd, 0x84ca30b3, "m...." },
  [5090] = { "Chiamata alle armi: le Plaguelands!", "Cerca Commander Ashlam Valorfist. Il suo campo base si trova al Chillwind Camp, a nord delle Alterac Mountains.", "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl regno di Stormwind ha lanciato una chiamata alle armi! Tutte le persone abili sono invitate a prendere le armi contro l'oscura minaccia degli Scourge nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!\n\nEroi del reame, cercate Commander Ashlam Valorfist, che ha stabilito il suo campo base al Chillwind Camp, a nord delle Alterac Mountains!", nil, "Ti do il benvenuto nelle Plaguelands, eroe. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente degli Scourge a nord e a nord-est. Mi fa piacere sapere che la chiamata al dovere e al servizio del bene comune non è caduta nel vuoto con te!\n\nSe sei <pronto/pronta> a sporcarti le mani, qui al margine delle Plaguelands c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xe8509ad0, "...m." },
  [5091] = { "Chiamata alle armi: le Plaguelands!", "Cerca Commander Ashlam Valorfist. Il suo campo base si trova al Chillwind Camp, a nord delle Alterac Mountains.", "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl regno di Stormwind ha lanciato una chiamata alle armi! Tutte le persone abili sono invitate a prendere le armi contro l'oscura minaccia degli Scourge nelle terre settentrionali degli Eastern Kingdoms! Corrono voci di nuove minacce che sorgono dalle rovine delle Plaguelands!\n\nEroi del reame, cercate Commander Ashlam Valorfist, che ha stabilito il suo campo base al Chillwind Camp, a nord delle Alterac Mountains!", nil, "Ti do il benvenuto nelle Plaguelands, eroe. È una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente degli Scourge a nord e a nord-est. Mi fa piacere sapere che la chiamata al dovere e al servizio del bene comune non è caduta nel vuoto con te!\n\nSe sei <pronto/pronta> a sporcarti le mani, qui al margine delle Plaguelands c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xe8509ad0, "...m." },
  [5093] = { "Chiamata alle armi: le Plaguelands!", nil, nil, nil, nil, 0x7b917538, nil, nil, nil, nil, ".mmmm" },
  [5094] = { "Chiamata alle armi: le Plaguelands!", nil, nil, nil, nil, 0x7b917538, nil, nil, nil, nil, ".mmmm" },
  [5095] = { "Chiamata alle armi: le Plaguelands!", nil, nil, nil, nil, 0x7b917538, nil, nil, nil, nil, ".mmmm" },
  [5102] = { "La fine del generale Drakkisath", "Viaggia fino alla Blackrock Spire e distruggi il generale Drakkisath. Torna dal Marshal Maxwell quando avrai finito.", "Combattiamo queste bestie su due fronti: dalla nostra capitale, Stormwind, le combattiamo dall'interno, e qui, nelle Burning Steppes, portiamo la battaglia alle loro porte. Dobbiamo essere vigili, {name}. Nessuno deve essere risparmiato dalla nostra ira, così come nessuno dei nostri è stato risparmiato quando hanno colpito le nostre case e le nostre famiglie.\n\nTrova questo generale Drakkisath e distruggilo!\n\nIl compito non sarà certo semplice, ma le ricompense saranno sontuose.", "È fatta?", "Di certo la prossima volta colpiremo i loro signori dei draghi. Ben fatto, valoroso soldato dell'Alleanza! Davvero ben fatto.", 0xda93b846, 0x12dc4302, 0x505fe600, 0xcd001c89, 0x72a4103b, "....." },
  [5144] = { "Lavorazione del cuoio elementale", "Porta $N1 Heart of Fire, $N2 Globe of Water, $N3 Core of Earth e $N4 Breath of Wind a Sarah Tanner, nella Searing Gorge.\n\nCompletare questa quest ti darà accesso alle arti della lavorazione del cuoio elementale.\n\nCompletare questa quest ti impedirà di imparare la lavorazione del cuoio con scaglie di drago e quella tribale; assicurati che sia la strada che vuoi seguire prima di farlo.", "La lavorazione del cuoio elementale è ciò che conosco, e se sei disposto ad aprire la mente ai poteri superiori della materia, condividerò con te tutto ciò che c'è da imparare.\n\nSappi questo, {class}: scegliendo questa strada accetti di non imparare mai la lavorazione del cuoio con scaglie di drago o quella tribale; c'è spazio per praticare una sola delle tre arti. Inoltre, mi servirà una prova adeguata che sei in sintonia con gli elementi della natura; a tal fine, portami le essenze più pure di fuoco, acqua, terra e vento.", "Creare questo tipo di armature in cuoio richiede pazienza e dedizione. Una volta legato il tuo destino agli elementi, non potrai più voltar loro le spalle. Portami la prova del tuo valore e cominceremo.", "Hai fatto la tua scelta, e gli elementi ti accettano. Quando avrò finito di istruirti, avrai la volontà di creare le migliori vesti di cuoio.\n\nPer continuare ad addestrarti nell'arte in futuro, parla semplicemente con me e ti renderò disponibile qualsiasi conoscenza che non hai ancora fatto tua.", 0x9503323d, 0x370e9a1c, 0xd87a1461, 0xae7f88b1, 0xe07be135, "....." },
  [5146] = { "Lavorazione del cuoio elementale", nil, "La lavorazione del cuoio elementale è ciò che conosco, e se sei disposto ad aprire la mente ai poteri superiori della materia, condividerò con te tutto ciò che c'è da imparare.\n\nSappi questo, {class}: scegliendo questa strada accetti di non imparare mai la lavorazione del cuoio con scaglie di drago o quella tribale; c'è spazio per praticare una sola delle tre arti. Inoltre, mi servirà una prova adeguata che sei in sintonia con gli elementi della natura; a tal fine, portami le essenze più pure di fuoco, acqua, terra e vento.", "Creare questo tipo di armature in cuoio richiede pazienza e dedizione. Una volta legato il tuo destino agli elementi, non potrai più voltar loro le spalle. Portami la prova del tuo valore e cominceremo.", "Hai fatto la tua scelta, e gli elementi ti accettano. Quando avrò finito di istruirti, avrai la volontà di creare le migliori vesti di cuoio.\n\nPer continuare ad addestrarti nell'arte in futuro, parla semplicemente con me e ti renderò disponibile qualsiasi conoscenza che non hai ancora fatto tua.", 0x9503323d, nil, 0xd87a1461, 0xae7f88b1, 0xe07be135, ".m..." },
  [5159] = { "L'acqua purificata torna a Felwood", "Porta la Purified Moon Well Water a Greta Mosshoof, a Felwood.", "Ringrazia gli spiriti, {name}. Sono loro che ti sono venuti in aiuto, non io.\n\nTi do ora quest'acqua purificata. Ti prego, porta i miei saluti a Greta e i miei migliori auguri. Sta affrontando qualcosa di più grande di molti di noi... come sono certo scoprirà presto.\n\nIl Shadow Council non è una forza da prendere alla leggera, {name}. Ricordalo.\n\nOra va'. Prendi l'acqua e torna da Greta.", "Ah, vedo che sei <tornato/tornata>, {name}. Bene. Hai trovato Islen nelle Barrens? O dobbiamo trovare un altro modo per raggiungere i nostri obiettivi?", "Quest'acqua dovrebbe bastare e avanzare per i nostri scopi.\n\nSono lieta di sapere che Islen è riuscita ad aiutarci. Il suo legame con gli spiriti dell'acqua è sempre stato forte. È anche saggia, ed è raro che gli spiriti non approvino il suo intento. Il fatto che entrambi abbiano benedetto il nostro compito mi dà speranza di essere sulla strada giusta.", 0x51c0ce90, 0xf96df8a9, 0x913e20cc, 0xecbf45be, 0xe41510cb, "....." },
  [5250] = { nil, "Trova Starfall a Winterspring e parla con Wynd Nightchaser.", "A Winterspring, a nord di Felwood, ci sono molte antiche rovine elfiche. È una terra dura, ma custodisce molti segreti e luoghi da esplorare.\n\nI miei studi qui mi tengono così occupato che da tempo non ho occasione di andare a Winterspring. Ma non c'è motivo per cui tu non debba andarci a studiare le rovine.\n\nGià che ci sei, cerca Wynd Nightchaser. Passa quasi tutto il suo tempo a Starfall e conosce bene la zona.\n\nDigli che sei <un/una> <mio/mia> <allievo/allieva>...", nil, "<Un/Una> <allievo/allieva> di Daryn Lightwind? Piacere di conoscerti, {name}.", nil, 0x9b1efe0a, 0xaff8bd19, nil, 0x4a9ac80d, "m..m." },
  [5253] = { nil, nil, nil, "Sì, {race}?", nil, nil, nil, nil, 0x98b629a5, nil, "mmm.m" },
  [5261] = { nil, "Parla con Eagan Peltskinner.", "Eagan Peltskinner cerca qualcuno che vada a caccia di lupi per lui. È una buona notizia, perché ultimamente vediamo molti più lupi nella Northshire Valley.\n\nSe ti interessa, parla con Eagan. Lo trovi su un lato dell'abbazia, sulla sinistra.", nil, "È vero. Cerco qualcuno che vada a caccia di qualche lupo per me! Sei tu quella persona?", nil, 0x1419ddfe, 0x80800b5d, nil, 0x8ef5cba7, "m..m." },
  [5262] = { nil, nil, nil, "Cos'hai lì, {name}?", nil, nil, nil, nil, 0x421c38bd, nil, "mmm.m" },
  [5283] = { "L'arte del fabbro d'armature", "Per diventare fabbro d'armature devi creare i seguenti oggetti e portarli a Grumnus: $N1 Ornate Mithril Helms, $N2 Ornate Mithril Boots, $N3 Ornate Mithril Breastplate.", "Allora hai preso la decisione intelligente.\n\nTra me e il vecchio Ironus non corre buon sangue. Quel fabbricante di giocattoli buono a nulla sa chi sono i veri artigiani da queste parti.\n\nLe guerre davvero grandi si vincono con una buona difesa. Quando arriva il momento, nessun attacco ti tirerà fuori dai guai.\n\nBene, mettiamoci al lavoro. Devi solo dimostrarmi di avere del talento grezzo. Dopodiché tirerò via tutte le impurità che ti restano e ti plasmerò in un fabbro d'armature. Lo sai come si lavora il mithril decorato, vero?", "Ah, non c'è niente come una bella abbronzatura da forgia. Si capisce chi ha le abbronzature migliori dai segni del grembiule.", "Ci siamo, {name}. Dopo questo non si torna più indietro. Non è troppo tardi per diventare un fabbricante di giocattoli, ehm, fabbro d'armi.\n\nConfido che prenderai la decisione giusta.", 0xc822f11d, 0x3f0b804d, 0x0d0704a7, 0x8f8d67b9, 0x7c6f74a3, "....." },
  [5284] = { "La via del fabbro d'armi", "Per diventare fabbro d'armi devi creare i seguenti oggetti e portarli a Ironus: $N1 Moonsteel Broadswords, $N2 Massive Iron Axes, $N3 Heavy Mithril Axes e $N4 Big Black Maces.", "Come fabbro d'armi scoprirai che il più delle volte saranno eroi e avventurieri a venire da te per l'equipaggiamento. Anche se a volte il carico di lavoro è insopportabile, le ricchezze ripagano ampiamente il mal di schiena e i polmoni pieni di cenere.\n\nOh sì, {name}, sono i fabbri d'armi ad avere tutto l'oro!\n\nSe vuoi unirti ai nostri ranghi, dovrai dimostrarmi che sai farmi guadagnare qualche moneta d'argento... cioè, dimostrarmi che hai la stoffa per essere <quello/quella> a cui rivolgersi quando servono armi di qualità superiore. Al lavoro!", "<Ironus è impegnato a impilare monete d'oro in ordinati mucchietti.>", "Era ora! Ho clienti che aspettano.\n\nDammi quella roba e fai attenzione. Stai per fare il primo passo nella tua carriera di fabbro d'armi.", 0x7b932606, 0xd99d8b08, 0xf74bbea6, 0xc129794c, 0xe8985a2b, ".....", nil, nil, 0xe475450f, nil, nil },
  [5301] = { "L'arte del fabbro d'armature", nil, nil, nil, nil, 0xc822f11d, nil, nil, nil, nil, ".mmmm" },
  [5302] = { "La via del fabbro d'armi", nil, nil, nil, nil, 0x7b932606, nil, nil, nil, nil, ".mmmm" },
  [5321] = { "Il dormiente si è svegliato", "Scorta Kerlonian Evershade da Liladris Moonriver, verso sud lungo la strada, per trovare la sua sacca a Darkshore.", "Stavo andando al Maestra's Post per incontrare Liladris Moonriver, ma ho deciso di fermarmi qui a fare un pisolino. Da quando mi sono svegliato dall'emerald dream, ho sempre tanto sonno...\n\n<sbadiglia>\n\nE non riesco a trovare le mie cose da nessuna parte! Ti dispiacerebbe aiutarmi a trovarle?\n\nSo che il Maestra's Post è a sud di qui, lungo la strada, ad Ashenvale. Venivo da quella parte...\n\nInfine, potrei addormentarmi, quindi se mai dovessi svegliarmi, usa il mio corno. Lo trovi nel forziere qui.", "Kerlonian è arrivato?", "Oh, sono così felice che Kerlonian ce l'abbia fatta! E sono sicura che lo troverò addormentato da qualche parte qui intorno, vero?\n\nGrazie per avergli mostrato la strada, {name}.", 0xaa562d09, 0x0598ad83, 0xf9beb9c8, 0x5a42fe8b, 0x57f32af8, "....." },
  [5501] = { "Il collezionista di ossa", "Porta 10 Kodo Bones dal Kodo Graveyard a Bibbly F'utzbuckle, alla Kormek's Hut.", "Siamo seduti su una miniera d'oro, ti dico, una miniera d'oro! Le ossa di kodo cambieranno il mondo per sempre... Ho clienti che ci fanno mobili, strumenti musicali e persino polvere esplosiva.\n\nC'è una carovana che passa a ritirare le mie ossa di kodo e poi le vende allo Shadowprey Village. Se vai al cimitero dei kodo a sud di qui e mi porti dieci ossa di kodo, ti darò qualcosa in cambio. Affare fatto?", "Hai le ossa? La carovana arriverà da un momento all'altro. Mi servono solo altre dieci ossa di kodo per toccare il record della mia carriera. Il record della mia carriera, ti dico!", "Ah, che bello! Le mie ossa!\n\nNon vedo l'ora che i ragazzi a casa vedano la mia faccia sulla copertina di Goblin'preneur. Sarò il goblin più ricco del mondo... e il mio insegnante di educazione fisica diceva che non sarei mai diventato nessuno.", 0xa1177fd1, 0x6c4f8089, 0x73788e03, 0xf2c18490, 0xf47c7c14, "....." },
  [5502] = { nil, nil, nil, "È un piacere rivederti, {name}. Hai svolto i compiti che ti sei <offerto/offerta> di fare durante la Children's Week?", nil, nil, nil, nil, 0xfd180aa5, nil, "mmm.m" },
  [5526] = { "Frammenti della Felvine", "Trova la Felvine a Dire Maul e procurane un frammento. Probabilmente potrai ottenerne uno solo con la morte di Alzzin the Wildshaper. Usa il Reliquary of Purity per sigillarvi dentro il frammento in modo sicuro e riportalo a Rabine Saturna, a Nighthaven, Moonglade.", "La tua conoscenza di Eldre'Thalas, Dire Maul, a Feralas, ora ti tornerà utile, {name}. Nella parte orientale della città in rovina, Alzzin the Wildshaper esercita il suo dominio corrotto. Vai lì con tutta la fretta necessaria e affronta qualunque sfida ti attenda.\n\nIl Fruit of Fertility, ora corrotto e diventato la Felvine, dovrebbe trovarsi vicino ad Alzzin. Quando lui cadrà, cattura tutta l'essenza della Felvine che puoi. Sigillala nel Reliquary e portamela.\n\nBuona fortuna, e che tu abbia la velocità di Cenarion.", "Con il Sealed Reliquary of Purity in nostro possesso sarà possibile non solo eliminare dal mondo una minaccia corruttrice, ma anche studiarla sotto la nostra attenta sorveglianza. Forse riusciremo persino a ideare nuovi mezzi per combattere la contaminazione della corruzione che minaccia da sempre Azeroth.\n\nSo che Milli non l'avrebbe voluto in nessun altro modo...", "È fatta, {class} dal grande valore, e con questo il Cenarion Circle ha un debito con te. Anche se la guerra è lontana dall'essere finita, è stata vinta una grande battaglia contro chi vorrebbe la nostra rovina.\n\nTi prego, accetta questo come segno della nostra eterna gratitudine. Sappi che qui sei <benvenuto/benvenuta> come <eroe/eroina> del Cenarion Circle per la tua grande impresa, {name}. Grazie.", 0xc529120d, 0xbcbf4d83, 0x558aeb85, 0x10072c8b, 0x41482f0f, "....." },
  [5527] = { "Un Reliquary of Purity", "Recati a Silithus e cerca un Reliquary of Purity tra le rovine di Southwind Village. Se riesci a trovarlo, riportalo a Rabine Saturna, a Nighthaven, Moonglade.", "Il primo passo è trovare un contenitore capace di contenere una sostanza estremamente corruttrice senza che chi lo maneggia ne subisca gli effetti nocivi. Conosco un solo tipo di congegno che potrebbe contenere qualcosa di immondo come la Felvine: un Reliquary of Purity.\n\nNel cuore delle terre desolate di Silithus si trovano i resti del villaggio degli elfi della notte noto come Southwind. So che lì ce n'era uno, moltissimi anni fa. Se vogliamo riuscirci, ho bisogno che tu setacci quelle rovine nella speranza di recuperarlo.", "Un Reliquary of Purity è un artefatto a sé. Ne furono creati pochi, e si pensava che quasi tutti fossero andati perduti nel tempo.\n\nAmmetto di sapere di quello di Southwind già da un po'. Sinceramente, con i crescenti disordini a Silithus, ho pensato di tenere i nostri segreti proprio così: segreti. Frugare e indagare avrebbe solo destato i sospetti dei nostri nemici.\n\nAhimè, il tempo dell'inerzia è finito, specialmente con la situazione a Eldre'Thalas.", "Davvero, sei <pieno/piena> di risorse come molti dicono. Il Cenarion Circle è benedetto ad averti al suo servizio.\n\nCon il Reliquary di nuovo nelle nostre mani, la mia mente è tranquilla. Mi sento più a mio agio nel chiederti non solo di affrontare un demone malvagio, ma anche di riportare un oggetto pericoloso nel farlo...", 0x981c408b, 0x70105b2e, 0x93f71390, 0x39eb133a, 0xe4f96df3, "....." },
  [5541] = { "Munizioni per Rumbleshot", "Porta la Rumbleshot's Ammo a Hegnar Rumbleshot, a Dun Morogh.", "Hegnar Rumbleshot vende armi da fuoco lungo la strada per Anvilmar. Fucilieri e squadre di mortai passano molto tempo ad addestrarsi vicino al suo negozio, e lui ha sempre bisogno di munizioni fresche.\n\nMa... l'ultima cassa di munizioni che gli ho mandato si è persa per strada. Il mio corriere ha detto di essersi accampato vicino alla Grizzled Den quando i wendigo l'hanno messo in fuga... e lo sciocco ha lasciato lì le munizioni di Rumbleshot!\n\n{name}, puoi recuperare quelle munizioni e portarle a Rumbleshot? Le sta aspettando e sono sicuro che è quasi a secco.", "Spero che tu non sia qui per le munizioni, perché le ho quasi finite!", "Ottimo, altre munizioni! La spedizione del vecchio Loslor è finalmente arrivata! Saranno in ritardo, ma come mi diceva sempre mio nonno: meglio tardi che mai!\n\nGrazie mille, {name}. Ho già dei compratori ansiosi di avere questa roba!", 0x6bdee02c, 0x4a7a3e42, 0x0214773d, 0x38170153, 0xa9ceafda, "....." },
  [5545] = { "Un fagotto di guai", "Porta 8 Bundles of Wood a Raelen, all'Eastvale Logging Camp.", "Ho un bel problema. Ho una scadenza imminente per un ordine di legname, e il tempo sta finendo. I lupi e gli orsi a nord di qui hanno cacciato i miei operai lontano dalle fascine di legna che avevano già tagliato.\n\nHo già parlato con Deputy Rainer perché si liberi degli animali, ma mi serve qualcuno che vada a raccogliere la legna. Se mi porti 8 fascine di legna, forse riuscirò a rispettare la scadenza.", "Quella scadenza non si allontana, {class}. Ti prego, sbrigati a raccogliere quelle fascine di legna.", "Eccellente! Grazie a te, dovrei riuscire a completare l'ordine in tempo. Per mostrarti la mia gratitudine, vorrei offrirti qualche moneta come compenso per il disturbo.\n\nGrazie e arrivederci.", 0x014730dc, 0xa7c51bc1, 0x3cba4cdf, 0x1f6b6abf, 0x45f9cae3, "....." },
  [5561] = { "Il raduno dei kodo", "Riporta cinque Tamed Kodo e il Kodo Kombobulator a Smeed Scrabblescrew, allo Scrabblescrew's Camp.", "Bibbly pensa di essere l'unico goblin a Desolace che sappia fare soldi. Beh, l'unica carovana abbastanza coraggiosa da viaggiare in queste zone dipende da me. Da quando ho imparato a rinvigorire e controllare i kodo anziani e morenti con il mio kodo kombobulator, il proprietario della carovana Cork, Rigger e io siamo entrati in società.\n\nPrendi il kombobulator e usalo su qualsiasi kodo antico, anziano o morente: darà una scossa alla bestia trasformandola in un kodo addomesticato e costringendola a seguirti. Una volta addomesticato un kodo, riportamelo.", "La carovana arriverà a breve; hai i cinque nuovi kodo addomesticati che ti avevo chiesto?", "<Smeed Scrabblescrew comincia a contare.>\n\nTre, quattro e cinque... eccellente, chiedo cinque kodo addomesticati e ottengo cinque kodo addomesticati... diventerò ricco... sì, ricchissimo! Spero di vedere la faccia verde di Bibbly quando saprà del mio successo!", 0x04bb1caf, 0xd279a8c8, 0x6b6406ad, 0x132725c5, 0x6e31573b, "....." },
  [5621] = { "Le vesti della luna", "Trova Sentinel Shaya e cura le sue ferite con Lesser Heal (Rank 2). Poi concedile Power Word: Fortitude e torna da Laurna Morninglight, a Dolanaar.", "Ho bisogno del tuo aiuto, {name}. Devo restare qui ad addestrare gli altri studenti, ma tu puoi aiutare una delle nostre Sentinels ferita, appena a sud di Dolanaar. Si è ferita pattugliando il paese e avrebbe bisogno del nostro aiuto. Si chiama Shaya.\n\nQuando la trovi, cura le sue ferite e poi fortifica il suo corpo con i tuoi incantesimi. Almeno la proteggerà più a lungo se finirà nei guai. Torna qui da me quando avrai fatto il tuo dovere verso Elune.", "I nostri incantesimi di Fortify sono molto potenti, Delor. Permettono ai nostri compagni di sopportare più ferite da ogni tipo di attacco e di sopravvivere in situazioni in cui normalmente cadrebbero. Ma è niente rispetto alle nostre capacità di guarigione. Non esistono guaritori migliori di un sacerdote: ricordatelo bene. Il tuo potere da solo può facilmente cambiare le sorti di una battaglia.", "Hai fatto bene e hai servito Elune. Per questo ti ringrazio.\n\nTi prego, prendi questa veste come segno della mia gratitudine. Significa che ti sei <guadagnato/guadagnata> il tuo posto nel nostro ordine. Se vuoi, indossala con orgoglio, ma in ogni caso ti riconosceremo sempre come parte di noi.\n\nVai con Elune, {name}, e grazie.", 0x73f2ce3b, 0x26c8717b, 0xf5680a7c, 0xdd03baf4, 0xb864207f, "....." },
  [5622] = { "Nelle grazie di Elune", "Parla con Laurna Morninglight, a Teldrassil.", "{name}, devi andare a Dolanaar quando avrai finito i tuoi affari qui a Shadowglen. Lì troverai Laurna Morninglight. Ti istruirà ancora nelle vie di Elune, ed è con lei che guadagnerai le tue prime vesti, segno del tuo ruolo di <sacerdote/sacerdotessa> di Elune.\n\nAbbi cura di te, e che tu sia <protetto/protetta> nei tuoi viaggi.", nil, "Sono felice di vedere che Shanda ti ha mandato a cercarmi, {name}. Insegnare le vie di Elune ai giovani sacerdoti mi dà grande soddisfazione.", 0x1f581c9a, 0x7edc7e4a, 0xe180ecac, nil, 0xfc0c1954, "...m.", nil, nil, 0xa4f739a2, nil, nil },
  [5623] = { "Nelle grazie della Luce", "Parla con Priestess Josetta, nella Elwynn Forest.", "Eccoti di nuovo, giovane <sacerdote/sacerdotessa>. È giunto il momento che tu impari di più sulla nostra fede. Quando avrai finito i compiti che hai qui a Northshire, cerca Priestess Josetta a Goldshire. Ha altro da insegnarti e ha saputo che stai diventando forte nelle vie della Luce. Non vede l'ora di istruirti ancora.", nil, "Sono felice che tu sia qui, {name}. Abbiamo molto di cui parlare riguardo al tuo futuro e al tuo cammino nella Luce.", 0xd5e3412d, 0xf024d04d, 0xfb192887, nil, 0x0ffe1fdc, "...m.", nil, nil, 0xc820e603, nil, nil },
  [5624] = { "Le vesti della Luce", "Trova Guard Roberts e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Priestess Josetta a Goldshire.", "Di solito propongo una piccola prova ai seguaci della Luce per saggiarne l'abilità. Voglio vedere se sono degni di indossare la loro prima veste: un segno che la chiesa approva apertamente <il/la> <sacerdote/sacerdotessa> e <lo/la> sostiene.\n\nMa questa volta la situazione è un po' diversa. Uno degli abitanti di Goldshire ha visto una guardia ferita vicino al lago, a est di qui. Si chiama Roberts. Trovalo, curalo, fortifica il suo corpo e torna qui. Se ci riesci, considererò superata la tua prova.", "Come forse hai già imparato, le nostre magie di guarigione sono vitali per la sopravvivenza della nostra gente in questi tempi duri, soprattutto per gli avventurieri e gli eroi che prendono le armi e la magia per respingere tante minacce diverse.\n\nFaresti bene a ricordare sempre quanto sia importante questa abilità. Unita alla Fortitude, rende i tuoi compagni molto più capaci in battaglia, perché potranno reggere un numero maggiore di colpi.\n\nNon lasciare che nessuno sminuisca la potenza delle tue magie.", "Eccellente, {name}, con un'altra guardia in salute là fuori ad aiutare il paese, saremo tanto più al sicuro. Sono lieta di vedere che stai già imparando a usare le tue capacità con saggezza. Se in qualunque momento ti senti <pronto/pronta> per altro addestramento, torna pure da me. Ma per ora prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle questa veste non serve.", 0x42e1e67f, 0xd5d19b32, 0x701bafd9, 0xe1f1d1b3, 0xb57951a7, ".....", nil, nil, 0x1e24900e, nil, nil },
  [5625] = { "Le vesti della Luce", "Trova il Mountaineer Dolf e cura le sue ferite con Lesser Heal (Rank 2). Poi concedigli Power Word: Fortitude e torna da Maxan Anvol, a Kharanos.", "Di solito è più o meno in questo periodo che chi ha il tuo potere viene messo alla prova per vedere se è degno di indossare le vesti che indicano il suo posto nella chiesa. Ma a dire il vero ho faccende più urgenti da sbrigare. Un cittadino di Kharanos è appena entrato a dirmi di un mountaineer ferito appena fuori città, a sud: si chiama Dolf.\n\nTu cura Dolf e dagli Fortitude, e considererò conclusa la tua prova. Che ne dici?", "Hai già trovato Dolf, {name}?\n\nProbabilmente l'hai già imparato, ma la nostra capacità di guarire è molto utile. Non solo possiamo curare i feriti, ma siamo vitali per la sopravvivenza di tutti quegli aspiranti eroi là fuori che cercano di farsi un nome. Con Fortitude ad aumentare i colpi che possiamo sopportare e la nostra magia curativa a tenerli in vita, non c'è niente che non possiamo superare!", "Eccellente, {name}, con un'altra guardia in salute là fuori ad aiutare il paese, saremo tanto più al sicuro. Sono lieta di vedere che stai già imparando a usare le tue capacità con saggezza. Se in qualunque momento ti senti <pronto/pronta> per altro addestramento, torna pure da me. Ma per ora prendi questa veste. Farà sapere agli altri che fai parte del nostro ordine. Se non vuoi indossarla, va bene lo stesso. Più avanti ci saranno altre prove, e per quelle questa veste non serve.", 0x42e1e67f, 0x4324dd9b, 0x0d9a711f, 0x0425d788, 0xb57951a7, "....." },
  [5626] = { "Nelle grazie della Luce", "Parla con Maxan Anvol, a Dun Morogh.", "Ehi! {name}! Hai un minuto?!\n\nSegui la Luce da abbastanza tempo da doverti presentare a Maxan Anvol, a Kharanos. Ti insegnerà di più sul cammino che stai seguendo e, se ne sarai <degno/degna>, ti darà la tua prima serie di vesti a indicare il tuo rango di <sacerdote/sacerdotessa>.\n\nOra muoviti! Appena hai finito qui, attraversa la galleria: ti starà aspettando.", nil, "Oh, quindi ti ha mandato Branstock, eh? Bene, bene! Ha ragione, è ora che tu faccia un passo molto più grande verso la Luce. Ti formerà il carattere e ti renderà più forte... ed è di questo che avrai bisogno più di ogni altra cosa: forza del corpo... forza di volontà.", 0xd5e3412d, 0x5cf188e4, 0x84b16634, nil, 0x77d8d926, "...m.", nil, nil, 0xb689446c, nil, nil },
  [5627] = { "Le stelle di Elune", nil, nil, nil, "Hai dimostrato di essere <degno/degna> dell'attenzione di Elune, {name}. Se ti senti <pronto/pronta>, vorrei molto insegnarti uno dei suoi incantesimi che appartengono solo al nostro popolo.", 0x8a355ee6, nil, nil, nil, 0x6f78fed8, ".mmm." },
  [5628] = { "Ritorno a casa", "Parla con Priestess Alathea, a Darnassus.", "Ah, sì, salve, {name}? Mi fa piacere che ti sia <fermato/fermata> a parlare un momento. Sei così <lontano/lontana> da casa a un'età così giovane: ammiro tanta ambizione. Vorrei aver trovato anch'io, da giovane, il coraggio di girare il mondo.\n\nNon molto tempo fa è passata di qui una sacerdotessa del tuo ordine a cercarti. Ha detto che era molto urgente che tornassi al Temple of the Moon, a Darnassus, e parlassi con Priestess Alathea: aveva a che fare con il tuo addestramento. Se puoi, non indugiare troppo.", nil, "Che meraviglia, sei <tornato/tornata> a casa, {name}. A me e a Tyrande fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti vanno le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della questione che ci riguarda, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x8242adf0, nil, 0x8d04e540, "...m." },
  [5629] = { "Ritorno a casa", "Parla con Priestess Alathea, a Darnassus.", "Salve di nuovo, {name}. So che sei <impegnato/impegnata> ad aiutare la nostra gente, ma devi anche prenderti un po' di tempo per te. La Priestess Alathea ha mandato qualcuno qui a cercarti. Sembra che tu abbia attirato l'attenzione dei nostri anziani e che ritengano tu sia <pronto/pronta> per cose più grandi. Va' al Temple of the Moon di Darnassus e cerca lì Alathea. Ti starà aspettando. Buona fortuna, e che Elune sia con te.", nil, "Magnifico, sei <tornato/tornata>, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato escono nel mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della questione in sospeso, potresti raccontarmi di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0xa8f3f5b8, nil, 0xcbab1194, "...m." },
  [5630] = { "Ritorno a casa", "Parla con Priestess Alathea, a Darnassus.", "Salve, <ragazzo/ragazza>. Fa piacere vederti viaggiare in lungo e in largo fino a terre lontane. Senza offesa, ma molti della tua gente di solito non sopportano bene questi climi freddi. Sono contento di vedere che sei <fatto/fatta> di una pasta più dura.\n\nNon molto tempo fa una delle vostre sacerdotesse è passata di qui a cercarti: ha detto qualcosa sul fatto che dovevi trovare una certa Priestess Alathea nel Temple of the Moon, a Darnassus. Ha detto che era importante e che dovresti tornarci presto.", nil, "Che meraviglia, sei <tornato/tornata> a casa, {name}. A me e a Tyrande fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti vanno le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della questione che ci riguarda, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x3b3bfab4, nil, 0x8d04e540, "...m.", nil, nil, 0x25879782, nil, nil },
  [5631] = { "Ritorno a casa", "Parla con Priestess Alathea, a Darnassus.", "Una sacerdotessa ha visitato di recente le nostre sale in cerca di te, {race}. Ha detto che era in missione per trovarti e che dovresti tornare al Temple of the Moon di Darnassus il prima possibile. Quando arrivi, cerca una certa Priestess Alathea: ti dirà di più.\n\nChe la Luce sia con te, {name}.", nil, "Che meraviglia, sei <tornato/tornata> a casa, {name}. A me e a Tyrande fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti vanno le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della questione che ci riguarda, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0xbd0e6a0c, nil, 0x8d04e540, "...m." },
  [5632] = { "Ritorno a casa", "Parla con Priestess Alathea, a Darnassus.", "Oh, sì, certo. Salve, {name}. Un messaggero del nostro ordine è passato di qui non molto tempo fa a cercarti. Ha accennato a qualcosa di importante che sta accadendo a Darnassus e ha detto che dovresti tornare al Temple of the Moon appena puoi. Quando arrivi, parla con la Priestess Alathea. Credo che abbia a che fare con i tuoi ottimi progressi nelle nostre vie.\n\nTe lo ripeto, torna a Darnassus quando puoi.", nil, "Che meraviglia, sei <tornato/tornata> a casa, {name}. A me e a Tyrande fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti vanno le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della questione che ci riguarda, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x9052d2b7, nil, 0x8d04e540, "...m." },
  [5633] = { "Ritorno a casa", "Parla con Priestess Alathea, a Darnassus.", nil, nil, "Che meraviglia, sei <tornato/tornata> a casa, {name}. A me e a Tyrande fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti vanno le cose? Elune benedice ancora i tuoi viaggi? Forse, dopo aver parlato della questione che ci riguarda, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, nil, nil, 0x8d04e540, "..mm." },
  [5634] = { nil, "Parla con High Priest Rohan, a Ironforge.", "Un sacerdote ha visitato di recente le nostre sale in cerca di te, {race}. Ha detto che era in missione per trovarti e che dovresti tornare alla Hall of Mysteries di Ironforge il prima possibile. Quando arrivi, cerca l'High Priest Rohan: ti dirà di più.\n\nChe la Luce sia con te, {name}.", nil, "Hai reso un grande servizio alla Luce diventando un esempio luminoso per chi viaggia in queste terre pericolose e oltre. Ti prego, accetta questa lezione come ringraziamento per tutto ciò che hai fatto.", nil, 0x18755abb, 0x16d5e391, nil, 0x8e6ca817, "m..m." },
  [5635] = { nil, "Parla con High Priest Rohan, a Ironforge.", "Hai attirato l'attenzione dei nostri superiori, {name}. Ti chiedono di recarti alla Hall of Mysteries di Ironforge il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e che sia <pronto/pronta> a proseguire l'addestramento. Quando arrivi, cerca High Priest Rohan: saprà guidarti oltre. Buona fortuna, e che la Luce sia con te.", nil, "Sono felice che tu sia qui, {name}. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei <pronto/pronta>, cominceremo a parlare di alcune di esse ora.", nil, 0x18755abb, 0x87560e73, nil, 0xddc02048, "m..m." },
  [5636] = { nil, "Parla con High Priest Rohan, a Ironforge.", "Che Elune ti benedica, {race}. Spero che la tua Luce ti trovi e ti protegga bene oggi.\n\nUno dei tuoi sacerdoti è passato di qui non molto tempo fa a cercarti. Ha detto che dovresti tornare alla Hall of Mysteries il prima possibile per parlare con l'High Priest Rohan. Sembra che tu abbia fatto bene, per attirare tanta attenzione. Non resterei qui troppo a lungo: la tua gente ha bisogno di te.", nil, "Sono felice che tu sia qui, {name}. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei <pronto/pronta>, cominceremo a parlare di alcune di esse ora.", nil, 0x18755abb, 0x829d5d51, nil, 0xddc02048, "m..m." },
  [5637] = { nil, "Parla con High Priest Rohan, a Ironforge.", "È ora che tu vada a Stormwind, {name}. L'High Priest Rohan, nella Hall of Mysteries, vuole parlarti. Dev'essere qualcosa di molto buono o di molto brutto se l'High Priest ti vuole lì di persona, ma immagino che tu abbia fatto solo bene e che sia una buona cosa che voglia parlarti.\n\nMa non perdere troppo tempo da queste parti. Io ci andrei appena possibile.", nil, "Sono felice che tu sia qui, {name}. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei <pronto/pronta>, cominceremo a parlare di alcune di esse ora.", nil, 0x18755abb, 0x148eb4c2, nil, 0xddc02048, "m..m." },
  [5638] = { nil, "Parla con High Priest Rohan, a Ironforge.", "Poco fa uno dei tuoi sacerdoti è passato di qui a cercarti, {race}. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Hall of Mysteries. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Il suo atteggiamento sembrava positivo... come se fossero buone notizie. Al tuo posto non ci metterei troppo ad arrivarci.\n\nChe Elune sia con te, {race}.", nil, "Sono felice che tu sia qui, {name}. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei <pronto/pronta>, cominceremo a parlare di alcune di esse ora.", nil, 0x18755abb, 0xa819c88b, nil, 0xddc02048, "m..m." },
  [5639] = { nil, nil, nil, nil, "Sono felice che tu sia qui, {name}. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei <pronto/pronta>, cominceremo a parlare di alcune di esse ora.", nil, nil, nil, nil, 0xddc02048, "mmmm." },
  [5640] = { nil, "Parla con l'High Priest Rohan, a Stormwind.", "Sia lodata Elune, e la tua Luce, {name}.\n\nPiù o meno in questo periodo molti del nostro ordine apprendono capacità che riflettono la loro fede in Elune. Se non sbaglio, credo che lo stesso valga anche per il tuo ordine.\n\nQuando avrai concluso i tuoi affari a Darnassus, cercherei uno dei tuoi High Priest per un ulteriore addestramento.", nil, "Sono felice che tu sia qui, {name}. Ci sono molte cose di cui dovremo parlare, ma la più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei <pronto/pronta>, cominceremo a parlare di alcune di esse ora.", nil, 0xa762cb1a, 0x62b6262b, nil, 0xddc02048, "m..m." },
  [5645] = { nil, "Parla con High Priest Rohan, a Ironforge.", "{name}, il tuo High Priest Rohan vorrebbe riceverti a Ironforge. Affrettati, <mio/mia> forte <amico/amica>: la tua prossima prova si avvicina rapidamente. Anche se vorrei poter assistere ai riti speciali della tua razza, il mio posto è qui. Ma che la Luce ti accompagni nei tuoi viaggi. Rohan dovrebbe essere ancora nel Mystic Ward quando arriverai in città. Ti starà aspettando.", nil, "È un bene che tu sia <venuto/venuta>, {name}. La nostra razza è fiera e forte, ed è tempo che tu impari non solo a esserlo tu <stesso/stessa>, ma anche a suscitare tali sentimenti e tale fiducia negli altri. Sei <pronto/pronta>, <ragazzo/ragazza>?", nil, 0x18755abb, 0x7c851f5d, nil, 0x2f8ef86f, "m..m." },
  [5647] = { nil, "Parla con High Priest Rohan, a Ironforge.", "La tua razza è così forte, {name}. Siamo fieri di chiamarvi alleati. E a ogni tramonto, tu e la tua gente vi avvicinate non solo alla scoperta delle vostre vere origini, ma anche alla grande sicurezza di essere sulla strada giusta in tante cose. Quella sensazione deve farti sentire trionfante.\n\nPoco fa è arrivata una notizia da Ironforge. Chiedeva che tu tornassi lì a parlare con l'High Priest Rohan, nel Mystic Ward. Non lo farei aspettare. Che Elune guidi i tuoi viaggi.", nil, "Hai la stoffa per diventare {class} di grande valore, {name}. Continua così!\n\n{name}Hai già dimostrato di essere <pronto/pronta> per la battaglia. Forse è ora di insegnarti qualcosina di più.", nil, 0x18755abb, 0x90bbdd69, nil, 0x3d1896c7, "m..m." },
  [5672] = { nil, nil, nil, nil, "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi possiamo raggiungere. È tradizione che, per la tua devozione, ti vengano insegnate capacità ancora più grandi. Accetti?", nil, nil, nil, nil, 0x8f606a4d, "mmmm." },
  [5673] = { nil, "Parla con Priestess Alathea, a Darnassus.", "Sai che puoi rivolgerti ai nostri istruttori in qualsiasi momento, {name}, ma ci sono alcune cose che non possiamo trasmetterti. Una di queste sono gli insegnamenti della tua dea Elune. Concede capacità speciali ai suoi fedeli e, se non sbaglio, è tempo che tu torni a casa, al tuo Temple of the Moon, per essere <messo/messa> alla prova.\n\nTorna lì quando puoi e parla con la Priestess Alathea.", nil, "Che Elune ti benedica per essere <tornato/tornata> così in fretta da noi. Questo è un momento importante del tuo addestramento, un momento che tutti nel nostro ordine prendono molto sul serio. Quando ti sarai <riposato/riposata> dal viaggio, ti prego, fammelo sapere. Potremo allora discutere della prosecuzione del tuo addestramento e di dove ti porterà il tuo cammino.", nil, 0x8f9be0c1, 0x8fb26a95, nil, 0xc3518a4a, "m..m." },
  [5674] = { nil, "Parla con Priestess Alathea, a Darnassus.", "È arrivato un giorno meraviglioso, {name}. Hai raggiunto l'età in cui i nostri <sacerdoti/sacerdotesse> vengono addestrati in capacità che solo gli elfi della notte conoscono. Ma non spetta a me addestrarti. Devi tornare al Temple of the Moon e parlare con la Priestess Alathea appena avrai concluso i tuoi affari qui. Ti metterà alla prova per assicurarsi che tu sia <pronto/pronta>, e solo allora ti insegnerà Elune's Grace.", nil, "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi possiamo raggiungere. È tradizione che, per la tua devozione, ti vengano insegnate capacità ancora più grandi. Accetti?", nil, 0x8f9be0c1, 0xda81f573, nil, 0x8f606a4d, "m..m.", nil, nil, 0x22b130fc, nil, nil },
  [5675] = { nil, "Parla con Priestess Alathea, a Darnassus.", nil, nil, "Che Elune ti benedica per essere <tornato/tornata> così in fretta da noi. Questo è un momento importante del tuo addestramento, un momento che tutti nel nostro ordine prendono molto sul serio. Quando ti sarai <riposato/riposata> dal viaggio, ti prego, fammelo sapere. Potremo allora discutere della prosecuzione del tuo addestramento e di dove ti porterà il tuo cammino.", nil, 0x8f9be0c1, nil, nil, 0xc3518a4a, "m.mm." },
  [5676] = { nil, nil, nil, nil, "Siamo stati costretti a imparare alcune magie per proteggerci da ciò che è comunemente chiamato il nostro più grande nemico: l'arcano.\n\nTi insegnerei un incantesimo per aiutarti a difendere te e i tuoi compagni da chi brandisce un tale potere.", nil, nil, nil, nil, 0x34be78ad, "mmmm." },
  [5677] = { nil, "Parla con High Priestess Laurena, a Stormwind.", nil, nil, "Ah, hai un tempismo perfetto, {name}. Cominciavo a chiedermi se tutti i miei messaggeri avessero avuto successo. Sono contenta di vedere di sì, altrimenti scommetto che saresti ancora in giro per il mondo a scoprire tutte le minacce che incombono sul nostro popolo.\n\nSei <pronto/pronta>? <Pronto/Pronta> per altro addestramento, intendo. Il tuo potere cresce più in fretta, e sento che sei <pronto/pronta> a imparare di più sulla nostra fede.", nil, 0x8de762b6, nil, nil, 0xa244b6c1, "m.mm." },
  [5678] = { nil, "Parla con High Priestess Laurena, a Stormwind.", "È ora che tu torni a Stormwind, giovane. I tuoi superiori ti hanno richiamato per altro addestramento. E anche se la cosa mi turba un po', la tua razza e la mia sono alleate, e non tradirei questa alleanza.\n\nNon voglio essere così reticente con te: la mia diffidenza verso le magie arcane, che siano di ispirazione divina o no, è ancora forte in me.\n\nCapirai di cosa parlo quando tornerai alla tua Cathedral of Light. Quando arrivi, parla con High Priestess Laurena.", nil, "Ah, hai un tempismo perfetto, {name}. Cominciavo a chiedermi se tutti i miei messaggeri avessero avuto successo. Sono contenta di vedere di sì, altrimenti scommetto che saresti ancora in giro per il mondo a scoprire tutte le minacce che incombono sul nostro popolo.\n\nSei <pronto/pronta>? <Pronto/Pronta> per altro addestramento, intendo. Il tuo potere cresce più in fretta, e sento che sei <pronto/pronta> a imparare di più sulla nostra fede.", nil, 0x8de762b6, 0x4fe1c26d, nil, 0xa244b6c1, "m..m." },
  [5713] = { "Un colpo. Un'uccisione.", "Proteggi Sentinel Aynasha, poi parla con Onaeya al Maestra's Post, ad Ashenvale.", "Stavo andando ad Auberdine con un messaggio importante quando sono stata attaccata dal furbolg Marosh e dai suoi inseguitori. Durante l'attacco sono stata avvelenata, e riesco a malapena a stare in piedi. Posso preparare un antidoto, ma ci vorrà tempo prima che sia pronto.\n\nTi chiederei di difendermi finché non potrò applicare l'antidoto. Ti aiuterò con il mio arco come posso.\n\nSe sopravviviamo, potrò consegnare il mio messaggio ad Auberdine, mentre tu parlerai con Onaeya al Maestra's Post per informarla dell'accaduto.", "Hai visto la Sentinel Aynasha lungo la strada? È partita per una missione importante, ma non è ancora tornata.", "Porti notizie graditissime, {class}. È bello sapere che Aynasha è viva e sta bene grazie a te. Spero che accetterai una ricompensa per il tuo valore. Che Elune vegli su di te e illumini il tuo cammino.", 0xd9bcb0ad, 0xfd45a006, 0x550eea3f, 0xd79229bb, 0x5150e92b, "....." },
  [5741] = { nil, "Prendi lo Sceptre of Light e riportalo ad Azore Aldamort, alla torre di Ethel Rethor.", "Si dice che la Burning Blade nella Thunder Axe Fortress, a est, abbia ottenuto dai naga lo Sceptre of Light. La leggenda narra che lo scettro sia in grado di far sprofondare intere città sotto i grandi mari. Non si deve permettere alla Burning Blade di possedere un tale potere.\n\nPer questo devi recuperare tu <stesso/stessa> lo scettro! È custodito da un veggente della Burning Blade, che lo studia dalla cima di una delle torri di guardia di Thunder Axe.", "Hai lo Sceptre of Light?", "L'inafferrabile Sceptre of Light! Ottenendolo, hai eliminato una grave minaccia per il mondo. Ben fatto, {class}, ben fatto.", nil, 0x5315a126, 0xfea822cf, 0x818ecd10, 0xbc6ea27a, "m...." },
  [5805] = { "Benvenuti!", "Porta il Northshire Gift Voucher a Merissa Stilwell.", "Benvenuti nel World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la World of Warcraft Collector's Edition, consegna questo buono regalo a Merissa Stilwell nella Northshire Valley. Riceverai un regalo: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza nel World of Warcraft!", "Salute! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero <un/una> <eroe/eroina> speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x507c2857, 0x1a0e6aca, 0x2524e445, 0x4c44dc2c, "....." },
  [5821] = { "Guardia del corpo a pagamento", "Scorta la Gizelton Caravan oltre il villaggio dei Kolkar Centaur. Parla con Smeed allo Scrabblescrew's Camp per la tua ricompensa.", "In circostanze normali, Rigger e io guideremmo il nostro kodo oltre i Kolkar Centaur. Ogni tanto sentiamo i tamburi di guerra dei centauri, e quando li sentiamo ci fermiamo. Non fa bene agli affari essere morti!\n\nTi dico una cosa, {class}: se ci proteggi oltre il villaggio dei Kolkar, ne varrà la pena.\n\nÈ solo un breve tratto: devi solo mantenere intatta la carovana e potrai ritirare la tua ricompensa da Smeed Scrabblescrew, poco più avanti lungo la strada. Facciamo un po' di affari insieme.", "Perché mi ritrovo ad aspettare quella maledetta carovana?\n\n<Smeed sembra illuminarsi.>\n\nAh già, pagano i conti. Li hai visti?", "Sai, non mi sembra un affare pagare gente come te per sorvegliare la Gizelton Caravan. {class}, se fossi un po' più alto potrei prendermi un secondo lavoro e sedermi in sella al kodo con il fucile più grosso che riesco a portare... e farei vedere a quei maledetti centauri chi comanda.", 0x998f3fc8, 0x0697bce1, 0xa4b4d23d, 0x65827a69, 0xb6a810e3, "....." },
  [5841] = { "Benvenuti!", "Porta il Coldridge Valley Gift Voucher a Yori Crackhelm.", "<Benvenuto/Benvenuta> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la World of Warcraft Collector's Edition, consegna questo buono regalo a Yori Crackhelm, a Coldridge Valley. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza in World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero <un/una> <eroe/eroina> speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x76066af0, 0x1ef929e0, 0xaec8f595, 0x4c44dc2c, "....." },
  [5842] = { "Benvenuti!", "Porta lo Shadowglen Gift Voucher a Orenthil Whisperwind.", "<Benvenuto/Benvenuta> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la World of Warcraft Collector's Edition, consegna questo buono regalo a Orenthil Whisperwind, a Shadowglen. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza in World of Warcraft!", "Salute! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero <un/una> <eroe/eroina> speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x30f931f5, 0x98375d78, 0x2524e445, 0x4c44dc2c, "....." },
  [5843] = { "Benvenuti!", nil, nil, "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero <un/una> <eroe/eroina> speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, nil, nil, 0xaec8f595, 0x4c44dc2c, ".mm.." },
  [5844] = { "Benvenuti!", nil, nil, "Salute! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero <un/una> <eroe/eroina> speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, nil, nil, 0x2524e445, 0x4c44dc2c, ".mm.." },
  [5847] = { "Benvenuti!", nil, nil, "Salute! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero <un/una> <eroe/eroina> speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, nil, nil, 0x2524e445, 0x4c44dc2c, ".mm.." },
  [5921] = { nil, "Usa l'incantesimo \"Teleport: Moonglade\" per andare a Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Tutti i druidi sono i benvenuti nelle terre sacre di Moonglade, nonostante le tensioni attuali nel Cenarion Circle tra Arch Druid Staghelm e Keeper Remulos, il guardiano di Moonglade. Ora che stai imparando le vie dell'artiglio, ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la saggezza o il conforto di Moonglade.\n\nQuanto alla tua prima lezione, vai a Moonglade e parla con Dendrite Starblaze, a Nighthaven, del cammino che hai intrapreso. Buona fortuna, giovane druido.", nil, "\"E così comincia, Father Cenarius. E così comincia.\"\n\nDendrite fa un rapido gesto invisibile nell'aria sopra di sé. Una leggera aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti metterò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo, ora e per sempre!\"", nil, 0xf8085429, 0x6d17554b, nil, 0xeca326e1, "m..m." },
  [5922] = { nil, "Usa l'incantesimo \"Teleport: Moonglade\" per andare a Moonglade. Quando arrivi, parla con Dendrite Starblaze nel villaggio di Nighthaven.", nil, nil, "\"E così comincia, Father Cenarius. E così comincia.\"\n\nDendrite fa un rapido gesto invisibile nell'aria sopra di sé. Una leggera aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti metterò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo, ora e per sempre!\"", nil, 0xf8085429, nil, nil, 0xeca326e1, "m.mm." },
  [5923] = { "Rispondere alla chiamata", "Parla con Mathrengyl Bearwalker, nel Cenarion Enclave, a Darnassus.", "Scusami, amico...\n\nHo saputo che Mathrengyl Bearwalker ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da druido stia per prendere una nuova vita, e sarà lui ad addestrarti di persona. Mathrengyl è l'assistente diretto dell'arcidruido in persona, ed è uno dei druidi più saggi e venerabili che troverai a Teldrassil.\n\nSi trova nel Cenarion Enclave di Darnassus, al secondo piano dell'albero di Fandral Staghelm.", nil, "Sono felice che oggi tu abbia trovato la strada fin qui, giovane druido. È giunto il momento di fare un grande passo in un mondo molto più grande.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Gli animali e le piante sono nostri amici oltre che nostri protetti. Scegliamo di dedicare la vita a preservare l'equilibrio per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x2b8e0102, "...m." },
  [5924] = { "Rispondere alla chiamata", "Parla con Mathrengyl Bearwalker, nel Cenarion Enclave, a Darnassus.", "Scusami, amico...\n\nHo saputo che Mathrengyl Bearwalker ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da druido stia per prendere una nuova vita, e sarà lui ad addestrarti di persona. Mathrengyl è l'assistente diretto dell'arcidruido in persona, ed è uno dei druidi più saggi e venerabili che troverai a Teldrassil.\n\nSi trova nel Cenarion Enclave di Darnassus, al secondo piano dell'albero di Fandral Staghelm.", nil, "Sono lieto che tu abbia trovato la strada fin qui oggi. giovane {class}. È giunto il momento che tu faccia un grande passo in un mondo molto più grande.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e anche nostre responsabilità. Scegliamo di dedicare la nostra vita a preservare l'equilibrio per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x65aa7f11, "...m." },
  [5925] = { "Rispondere alla chiamata", "Parla con Mathrengyl Bearwalker, nel Cenarion Enclave, a Darnassus.", "Scusami, amico...\n\nHo saputo che Mathrengyl Bearwalker ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da druido stia per prendere una nuova vita, e sarà lui ad addestrarti di persona. Mathrengyl è l'assistente diretto dell'arcidruido in persona, ed è uno dei druidi più saggi e venerabili che troverai a Teldrassil.\n\nSi trova nel Cenarion Enclave di Darnassus, al secondo piano dell'albero di Fandral Staghelm.", nil, "Sono felice che oggi tu abbia trovato la strada fin qui, giovane druido. È giunto il momento di fare un grande passo in un mondo molto più grande.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Gli animali e le piante sono nostri amici oltre che nostri protetti. Scegliamo di dedicare la vita a preservare l'equilibrio per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x2b8e0102, "...m." },
  [5926] = { "Rispondere alla chiamata", nil, nil, nil, nil, 0xfe4e1687, nil, nil, nil, nil, ".mmmm" },
  [5927] = { "Rispondere alla chiamata", nil, nil, nil, "Sono lieto che tu abbia trovato la strada fin qui oggi. giovane {class}. È giunto il momento che tu faccia un grande passo in un mondo molto più grande.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e anche nostre responsabilità. Scegliamo di dedicare la nostra vita a preservare l'equilibrio per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, nil, nil, nil, 0x65aa7f11, ".mmm." },
  [5928] = { "Rispondere alla chiamata", nil, nil, nil, "Sono lieto che tu abbia trovato la strada fin qui oggi. giovane {class}. È giunto il momento che tu faccia un grande passo in un mondo molto più grande.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e anche nostre responsabilità. Scegliamo di dedicare la nostra vita a preservare l'equilibrio per il loro bene e per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso, e imparare la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, nil, nil, nil, 0x65aa7f11, ".mmm." },
  [5929] = { "Il Great Bear Spirit", "Cerca il Great Bear Spirit nel nord-ovest di Moonglade e scopri cosa ha da insegnarti sulla natura dell'orso. Quando avrai finito, torna da Dendrite Starblaze, a Nighthaven, Moonglade.", "Nella parte nord-occidentale di Moonglade si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato insegnante e mentore nella prima vera comprensione naturale dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.\n\nVa' ora dal Great Bear Spirit e impara ciò che ti insegnerà. Quando sarà soddisfatto di te, torna da me qui a Nighthaven. Vedremo allora se hai davvero fatto tesoro delle sue lezioni.", "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può proseguire senza la sua benedizione.", "Mentre ti avvicini, Dendrite compie un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere lo avvolge e lui sorride appena.\n\n\"Percepisco in te una saggezza, giovane, che non c'era quando ci siamo incontrati la prima volta. Mi guardi con forza e intenzione consapevole, anche se questa intenzione non è ancora focalizzata. Ora imparerai a focalizzare la tua forza e ad adottare la natura dell'orso nel tuo operato.\"", 0xf41bfb43, 0xbe60f9ec, 0xfdf1fe79, 0x63fce517, 0x63faa67b, "....." },
  [5930] = { "Il Great Bear Spirit", "Cerca il Great Bear Spirit nel nord-ovest di Moonglade e scopri cosa ha da insegnarti sulla natura dell'orso. Quando avrai finito, torna da Dendrite Starblaze, a Nighthaven, Moonglade.", "Nella parte nord-occidentale di Moonglade si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato insegnante e mentore nella prima vera comprensione naturale dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.\n\nVa' ora dal Great Bear Spirit e impara ciò che ti insegnerà. Quando sarà soddisfatto di te, torna da me qui a Nighthaven. Vedremo allora se hai davvero fatto tesoro delle sue lezioni.", "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può proseguire senza la sua benedizione.", "Mentre ti avvicini, Dendrite compie un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere lo avvolge e lui sorride appena.\n\n\"Percepisco in te una saggezza, giovane, che non c'era quando ci siamo incontrati la prima volta. Mi guardi con forza e intenzione consapevole, anche se questa intenzione non è ancora focalizzata. Ora imparerai a focalizzare la tua forza e ad adottare la natura dell'orso nel tuo operato.\"", 0xf41bfb43, 0xbe60f9ec, 0xfdf1fe79, 0x63fce517, 0x63faa67b, "....." },
  [5931] = { "Ritorno a Darnassus", "Torna a Darnassus e parla con Mathrengyl Bearwalker, nel Cenarion Enclave.", "È giunto il momento di separarci, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Mathrengyl Bearwalker cammina davvero in equilibrio con la natura, pur vivendo pericolosamente vicino al luogo dove l'equilibrio ha vacillato. Ascolta le sue istruzioni e presto completerai le tue prime lezioni nel tuo ruolo di <protettore/protettrice> dell'equilibrio.\n\nVa' ora, giovane. Ci incontreremo di nuovo.", nil, "<Bentornato/Bentornata>, {name}. Percepisco che il tuo primo incontro con il Great Bear Spirit è stato come quello di tutti i druidi quando intraprendono il sentiero dell'artiglio... un po' sconcertante, ma molto intenso. So che per me è stato così.\n\nIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Ci siamo affidati alla sua saggezza e al suo potere per alimentare il nostro scopo. È giunto il momento della tua prima prova di questo scopo. Ascolta attentamente...", 0xf19243a5, 0x17d4d4c5, 0x96c7c00f, nil, 0x0683c922, "...m." },
  [5943] = { "La carovana Gizelton", "Scorta la Gizelton Caravan attraverso il Mannoroc Coven. Parla con Smeed allo Scrabblescrew's Camp per la tua ricompensa.", "Sembri qualcuno della razza {race} che sa il fatto suo. Forse cerchi di guadagnare qualche soldo? Cork e io abbiamo messo su questa carovana per fare un sacco di soldi; non immaginavamo i pericoli del guadagno!\n\nPiù avanti c'è il Mannoroc Coven... di solito i demoni ci ignorano, ma questa volta qualcosa ha spaventato i kodo. Ti pagherò per proteggere la carovana oltre il Mannoroc Coven. Una volta superato sani e salvi, potrai ricevere la tua ricompensa dal nostro socio d'affari Smeed, allo Scrabblescrew's Camp.", "Sai, se quella carovana sparisse sarei rovinato! Non mi porti per caso cattive notizie sulla carovana, vero?\n\n<Smeed si asciuga la fronte.>\n\nSia ringraziata la dea dell'avidità!", "Non sono sicuro che sia un affare pagare così tanti soldi per proteggere la Gizelton Caravan. Cork e Rigger guadagnano solo una moneta d'oro a settimana, ma finché continuano a pagarmi i kodo, poco mi importa di come gestiscono i loro affari.", 0x263585ae, 0x8ba6f882, 0x4d9b60f3, 0xdd8ee6b2, 0xc76ce493, "....." },
})
